const game={started:false,money:420,oil:72,capacity:100,carried:0,inventory:0,depth:0,running:false,onTop:false,climbing:false,groundY:0,velocityY:0,yaw:0,pitch:0,keys:{},joy:{x:0,y:0},sprinting:false,upgrades:{power:0,speed:0,capacity:0,efficiency:0,heat:0,durability:0},lastLayer:0,toastTimer:0,modal:null,resourceTimer:0,particles:[],mobileLook:false};
const player={pos:new THREE.Vector3(0,0,14),radius:.38,height:1.72};camera.position.set(0,1.62,14);game.yaw=0;
const ui={splash:$('#splash'),hud:$('#hud'),depth:$('#depth'),layer:$('#layer'),layerIndex:$('#layer-index'),depthFill:$('#depth-fill'),progress:$('#progress'),money:$('#money'),oilCount:$('#oil-count'),oilFill:$('#oil-fill'),status:$('#status'),rigState:$('#rig-state'),speed:$('#drill-speed'),objective:$('#objective'),prompt:$('#prompt'),carry:$('#carry'),modalLayer:$('#modal-layer'),modal:$('#modal'),toast:$('#toast'),note:$('#note'),crosshair:$('#crosshair'),arrival:$('#arrival')};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function notify(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(game.toastTimer);game.toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2400)}
function formatMoney(n){return '$ '+Math.floor(n).toLocaleString('en-US')}
function currentLayer(){let i=0;for(let j=0;j<layers.length;j++)if(game.depth>=layers[j].depth)i=j;return i}
function updateHUD(){const layerIndex=currentLayer(),pct=clamp(game.depth/3000*100,0,100);ui.depth.textContent=Math.floor(game.depth).toLocaleString();ui.layer.textContent=layers[layerIndex].name;ui.layerIndex.textContent=`${String(layerIndex+1).padStart(2,'0')} / 12`;ui.depthFill.style.width=pct+'%';ui.progress.textContent=pct.toFixed(1)+'%';ui.money.textContent=formatMoney(game.money);ui.oilCount.innerHTML=`${Math.floor(game.oil)} <small>/ ${game.capacity} L</small>`;ui.oilFill.style.width=clamp(game.oil/game.capacity*100,0,100)+'%';ui.status.textContent=game.running?'DRILLING':'STANDBY';ui.status.className='status '+(game.running?'running':'stopped');ui.rigState.textContent=game.running?'BIT IN OPERATION':game.oil<=0?'OUT OF OIL':'AWAITING INPUT';ui.speed.innerHTML=`DRILL POWER <b>${String(game.upgrades.power+1).padStart(2,'0')}</b>`;ui.carry.classList.toggle('hidden',game.carried<=0);}
function showLayer(i){const e=document.createElement('div');e.className='layer-discovery';e.innerHTML=`<small>GEOLOGICAL LAYER ${String(i+1).padStart(2,'0')} / 12</small><strong>${layers[i].name}</strong><em>${layers[i].effect}</em>`;$('#game').appendChild(e);setTimeout(()=>e.remove(),3400);}
function updateDepthVisual(){const idx=currentLayer(),layer=layers[idx];groundMat.color.setHex(0x77705a);const inside=scene.getObjectByName('inside');if(inside){inside.material.color.setHex(layer.color);inside.material.emissive.setHex(layer.color);inside.material.emissiveIntensity=idx>=8?.28:0}if(idx>=8){scene.fog.color.setHex(idx>=9?0x49271e:0x382a26);scene.fog.density=.011}else{scene.fog.color.setHex(0xa8b7b4);scene.fog.density=.009}if(idx>=9)hemi.intensity=1.3+game.upgrades.heat*.08;}
