document.addEventListener('contextmenu',e=>e.preventDefault());renderer.domElement.addEventListener('click',()=>{if(game.started&&!game.modal&&!document.pointerLockElement&&innerWidth>720)renderer.domElement.requestPointerLock?.();else if(game.started&&!game.modal)operateDrill()});
function dist(x,z){return Math.hypot(player.pos.x-x,player.pos.z-z)}
function nearestAction(){if(!game.started||game.modal)return null;if(game.climbing)return {label:'DESCEND THE STAIRS',kind:'climb'};if(game.onTop&&dist(1.45,.9)<2)return {label:game.carried?'REFILL RIG WITH OIL':'CHECK OIL REFILL PORT',kind:'refill'};if(dist(-19,4.7)<3.2)return {label:'OPEN OIL DEPOT',kind:'shop'};if(dist(-11,4.8)<3.4)return {label:'ENTER SCIENCE LAB',kind:'lab'};if(dist(0,0)<6.6)return {label:game.running?'STOP DRILL RIG':'START DRILL RIG',kind:'rig'};if(dist(3.6,-3)<2.1&&!game.onTop)return {label:'CLIMB TO RIG TOP',kind:'climb'};if(game.carried&&dist(0,0)<7)return {label:'CLIMB RIG STAIRS WITH OIL',kind:'climb'};return null}
function interact(){const a=nearestAction();if(!a){notify('Nothing to interact with nearby.');return}if(a.kind==='shop'){openShop();return}if(a.kind==='lab'){openLab();return}if(a.kind==='rig'){operateDrill();return}if(a.kind==='climb'){if(game.onTop){game.climbing=true;game.climbFrom=camera.position.clone();game.climbTo=new THREE.Vector3(3.6,1.62,5.4);game.climbTime=0;game.onTop=false;notify('Descending from the rig deck.')}else{game.climbing=true;game.climbFrom=camera.position.clone();game.climbTo=new THREE.Vector3(2.4,11.42,1.25);game.climbTime=0;notify('Climbing the rig stairs...');}return}if(a.kind==='refill'){if(!game.carried){notify('Purchase a canister at the oil depot first.');return}const fill=Math.min(game.carried,game.capacity-game.oil);if(fill<=0){notify('Tank is already at full capacity.');return}game.oil+=fill;game.carried-=fill;game.pouring=1.6;notify(`Pouring ${fill} L into the rig tank.`);updateHUD();return}}
function operateDrill(){if(!game.started||game.modal)return;if(dist(0,0)>7.1){notify('Get closer to the drill rig controls.');return}if(game.running){game.running=false;notify('Drill rig stopped.')}else if(game.oil<=0){notify('Rig is out of oil — refill at the top deck.');return}else if(game.depth>=3000){notify('The inner core is reached. Mission complete!');return}else{game.running=true;notify('Drill rig engaged — keep an eye on oil and temperature.')}updateHUD()}
function jump(){if(!game.started||game.climbing||game.modal)return;if(player.pos.y<.03){game.velocityY=5.1}}
function collides(x,z){if(Math.abs(x)>21.3||Math.abs(z)>19.2)return true;for(const b of [{x:-11,z:0,w:8,d:7},{x:-19,z:1,w:7,d:6}]){if(Math.abs(x-b.x)<b.w/2+.38&&Math.abs(z-b.z)<b.d/2+.38&&z<b.z+b.d/2-.6)return true}return false}
function updatePlayer(dt){if(!game.started||game.modal||game.climbing)return;const forward=(game.keys.KeyW||game.keys.ArrowUp?1:0)-(game.keys.KeyS||game.keys.ArrowDown?1:0)-game.joy.y;const side=(game.keys.KeyD||game.keys.ArrowRight?1:0)-(game.keys.KeyA||game.keys.ArrowLeft?1:0)+game.joy.x;const len=Math.hypot(forward,side)||1,sprint=game.sprinting||game.keys.ShiftLeft||game.keys.ShiftRight,speed=sprint?7.2:4.15;const dx=(Math.sin(game.yaw)*forward+Math.cos(game.yaw)*side)*speed*dt/len,dz=(-Math.cos(game.yaw)*forward+Math.sin(game.yaw)*side)*speed*dt/len;let nx=player.pos.x+dx,nz=player.pos.z+dz;if(!collides(nx,player.pos.z))player.pos.x=nx;if(!collides(player.pos.x,nz))player.pos.z=nz;if(player.pos.y>0||game.velocityY>0){game.velocityY-=14*dt;player.pos.y=Math.max(0,player.pos.y+game.velocityY*dt);if(player.pos.y===0)game.velocityY=0}camera.position.set(player.pos.x,player.pos.y+1.62,player.pos.z);camera.rotation.set(game.pitch,game.yaw,0,'YXZ')}
function updateClimb(dt){if(!game.climbing)return;game.climbTime+=dt;const t=clamp(game.climbTime/4.2,0,1);const smooth=t*t*(3-2*t);camera.position.lerpVectors(game.climbFrom,game.climbTo,smooth);camera.rotation.set(-.1,game.yaw,0,'YXZ');player.pos.set(camera.position.x,camera.position.y-1.62,camera.position.z);if(t>=1){game.climbing=false;game.onTop=game.climbTo.y>5;player.pos.set(camera.position.x,Math.max(0,camera.position.y-1.62),camera.position.z);notify(game.onTop?'Rig top deck reached. E at the refill port to pour oil.':'Back on the ground.');}}
function spawnChip(){const idx=currentLayer(),color=layers[idx].color;const mesh=new THREE.Mesh(new THREE.IcosahedronGeometry(.08+Math.random()*.14,0),new THREE.MeshStandardMaterial({color,roughness:.7,emissive:color,emissiveIntensity:.18}));mesh.position.set((Math.random()-.5)*2,.1+Math.random()*1.5,(Math.random()-.5)*2);scene.add(mesh);game.particles.push({mesh,life:1.6,velocity:new THREE.Vector3((Math.random()-.5)*2,Math.random()*2,(Math.random()-.5)*2)})}
function updateDrill(dt){if(game.pouring>0)game.pouring=Math.max(0,game.pouring-dt);if(!game.running)return;const layer=currentLayer(),power=game.upgrades.power,speed=1.05+game.upgrades.speed*.46;const hardness=1+Math.max(0,layer-2)*.12;if(power+1<Math.max(1,layer-2)){game.running=false;notify(`Formation too hard. Upgrade Drill Power to break ${layers[layer].name}.`);updateHUD();return}game.depth=Math.min(3000,game.depth+speed*dt/hardness);const consumption=(.34/(1+game.upgrades.efficiency*.14))*dt;game.oil=Math.max(0,game.oil-consumption);if(game.oil<=0){game.running=false;notify('Oil depleted — climb to the top deck and refill.');}game.resourceTimer+=dt;if(game.resourceTimer>12){game.resourceTimer=0;const reward=layers[currentLayer()].value+game.upgrades.power*8;game.money+=reward;notify(`${layers[currentLayer()].resource} recovered · +${formatMoney(reward)}`)}if(Math.random()<dt*2.7)spawnChip();const newLayer=currentLayer();if(newLayer!==game.lastLayer){game.lastLayer=newLayer;showLayer(newLayer);updateDepthVisual();if(newLayer===11){game.running=false;notify('MISSION COMPLETE — INNER CORE REACHED!');}}if(game.depth>=3000)game.running=false;}
