 document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer.domElement){game.yaw-=e.movementX*.0022;game.pitch=clamp(game.pitch-e.movementY*.0018,-1.35,1.35)}});
 document.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();game.keys[e.code]=true;if(e.code==='Escape'){if(game.modal)closeModal();else if(!$('#map-overlay').classList.contains('hidden'))$('#map-overlay').classList.add('hidden')}if(e.code==='KeyE')interact();if(e.code==='Space'&&!e.repeat)jump();if(e.code==='KeyF')operateDrill()});document.addEventListener('keyup',e=>game.keys[e.code]=false);
 document.addEventListener('contextmenu',e=>e.preventDefault());renderer.domElement.addEventListener('click',()=>{if(game.started&&!game.modal&&!document.pointerLockElement&&innerWidth>720)renderer.domElement.requestPointerLock?.();else if(game.started&&!game.modal)operateDrill()});
 function dist(x,z){return Math.hypot(player.pos.x-x,player.pos.z-z)}
-function nearestAction(){if(!game.started||game.modal)return null;if(game.climbing)return {label:'DESCEND THE STAIRS',kind:'climb'};if(game.onTop&&dist(1.45,.9)<2)return {label:game.carried?'REFILL RIG WITH OIL':'CHECK OIL REFILL PORT',kind:'refill'};if(dist(-19,4.7)<3.2)return {label:'OPEN OIL DEPOT',kind:'shop'};if(dist(-11,4.8)<3.4)return {label:'ENTER SCIENCE LAB',kind:'lab'};if(dist(0,0)<6.6)return {label:game.running?'STOP DRILL RIG':'START DRILL RIG',kind:'rig'};if(dist(3.6,-3)<2.1&&!game.onTop)return {label:'CLIMB TO RIG TOP',kind:'climb'};if(game.carried&&dist(0,0)<7)return {label:'CLIMB RIG STAIRS WITH OIL',kind:'climb'};return null}
+function nearestAction(){if(!game.started||game.modal)return null;if(game.climbing)return {label:'DESCEND THE STAIRS',kind:'climb'};if(game.onTop&&dist(1.45,.9)<2)return {label:game.carried?'REFILL RIG WITH OIL':'CHECK OIL REFILL PORT',kind:'refill'};if(dist(-19,4.7)<3.2)return {label:'OPEN OIL DEPOT',kind:'shop'};if(dist(-11,4.8)<3.4)return {label:'ENTER SCIENCE LAB',kind:'lab'};if(dist(3.6,-3)<2.1&&!game.onTop)return {label:'CLIMB TO RIG TOP',kind:'climb'};if(game.carried&&dist(0,0)<7)return {label:'CLIMB RIG STAIRS WITH OIL',kind:'climb'};if(dist(0,0)<6.6)return {label:game.running?'STOP DRILL RIG':'START DRILL RIG',kind:'rig'};return null}
 function interact(){const a=nearestAction();if(!a){notify('Nothing to interact with nearby.');return}if(a.kind==='shop'){openShop();return}if(a.kind==='lab'){openLab();return}if(a.kind==='rig'){operateDrill();return}if(a.kind==='climb'){if(game.onTop){game.climbing=true;game.climbFrom=camera.position.clone();game.climbTo=new THREE.Vector3(3.6,1.62,5.4);game.climbTime=0;game.onTop=false;notify('Descending from the rig deck.')}else{game.climbing=true;game.climbFrom=camera.position.clone();game.climbTo=new THREE.Vector3(2.4,11.42,1.25);game.climbTime=0;notify('Climbing the rig stairs...');}return}if(a.kind==='refill'){if(!game.carried){notify('Purchase a canister at the oil depot first.');return}const fill=Math.min(game.carried,game.capacity-game.oil);if(fill<=0){notify('Tank is already at full capacity.');return}game.oil+=fill;game.carried-=fill;game.pouring=1.6;notify(`Pouring ${fill} L into the rig tank.`);updateHUD();return}}
 function operateDrill(){if(!game.started||game.modal)return;if(dist(0,0)>7.1){notify('Get closer to the drill rig controls.');return}if(game.running){game.running=false;notify('Drill rig stopped.')}else if(game.oil<=0){notify('Rig is out of oil — refill at the top deck.');return}else if(game.depth>=3000){notify('The inner core is reached. Mission complete!');return}else{game.running=true;notify('Drill rig engaged — keep an eye on oil and temperature.')}updateHUD()}
 function jump(){if(!game.started||game.climbing||game.modal)return;if(player.pos.y<.03){game.velocityY=5.1}}
 function collides(x,z){if(Math.abs(x)>21.3||Math.abs(z)>19.2)return true;for(const b of [{x:-11,z:0,w:8,d:7},{x:-19,z:1,w:7,d:6}]){if(Math.abs(x-b.x)<b.w/2+.38&&Math.abs(z-b.z)<b.d/2+.38&&z<b.z+b.d/2-.6)return true}return false}

