node --input-type=module <<'EOF'
import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch(config.browser.launchOptions);
mkdirSync('/tmp/opencode', { recursive: true });
for (const [name, viewport] of [['desktop', {width:1440,height:900}], ['mobile', {width:390,height:844}]]) {
  const page = await browser.newPage({viewport});
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://localhost:4173/', {waitUntil:'load'});
  await page.locator('#start').click();
  await page.waitForTimeout(4500);
  if (name === 'desktop') {
    await page.keyboard.down('w'); await page.waitForTimeout(1900); await page.keyboard.up('w');
    const prompt = await page.locator('#prompt').innerText();
    await page.keyboard.press('e');
    await page.waitForTimeout(1800);
    const status = await page.locator('#status').innerText();
    const depth = Number((await page.locator('#depth').innerText()).replaceAll(',',''));
    const oil = await page.locator('#oil-count').innerText();
    console.log(JSON.stringify({name,prompt,status,depth,oil,errors}));
    if (!status.includes('DRILLING') || depth <= 0 || errors.length) process.exitCode = 1;
  } else {
    const controls = await page.locator('#mobile-controls').isVisible();
    console.log(JSON.stringify({name,controls,errors}));
    if (!controls || errors.length) process.exitCode = 1;
  }
  await page.screenshot({path:`/tmp/opencode/final-${name}.jpg`,type:'jpeg',quality:72});
  await page.close();
}
await browser.close();
EOF

