  const prompt=await page.locator('#prompt').innerText();await page.keyboard.press('e');await page.waitForTimeout(250);const toast=await page.locator('#toast').innerText();
  await page.waitForTimeout(3000);const status=await page.locator('#status').innerText();const depth=Number((await page.locator('#depth').innerText()).replaceAll(',',''));const oil=await page.locator('#oil-count').innerText();
  console.log(JSON.stringify({name,prompt,toast,status,depth,oil,errors}));
  if(!prompt.includes('START DRILL RIG')||!status.includes('DRILLING')||depth<=0||errors.length)process.exitCode=1;
 }else{
  const controls=await page.locator('#mobile-controls').isVisible();console.log(JSON.stringify({name,controls,errors}));if(!controls||errors.length)process.exitCode=1;
 }
 await page.screenshot({path:`/tmp/opencode/final-${name}.jpg`,type:'jpeg',quality:72});await page.close();
}
await browser.close();
EOF

